export async function confined(root: string, input: string, newPath = false): Promise<string> {
  const base = await realpath(root);
  const resolved = path.resolve(base, input);
  let existing = resolved;
  if (newPath) {
    while (true) {
      try { await stat(existing); break; } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
        const parent = path.dirname(existing);
        if (parent === existing) throw error;
        existing = parent;
      }
    }
  }
  const actual = await realpath(existing);
  const under = (p: string) => {
    const relative = path.relative(base, p);
    return relative !== '..' && !relative.startsWith('..' + path.sep) && !path.isAbsolute(relative);
  };
  if (!under(resolved) || !under(actual)) throw new Error('Path is outside the MCP workspace root.');
  return resolved;
}

export async function inspect(input: string, file?: string) {
  if (file || /\.(?:[cm]?js|jsx)$/i.test(input)) {
    const result = analyze(await loadSource(input, file));
    const { code: _code, fragments: _fragments, ...summary } = result;
    return summary;
  }
  return inventory(input);
}

export async function plan(input: string, file: string | undefined, selector: Selector) {
  const result = await moduleGraph(input, file, selector);
  return { source: { target: result.source.target, kind: result.source.kind, module: result.source.module, sha256: result.source.sha256 }, plan: result.plan, executesTarget: false };
}

