  server.registerTool('carve_search',{description:'Search only observations matching the current inventory bytes. Returns bounded excerpts and evidence IDs, not semantic confidence.',inputSchema:{...workspace,query:z.string().min(1).max(1000),limit:z.number().int().min(1).max(100).optional()},annotations:{readOnlyHint:true,openWorldHint:false}},args=>guarded(async()=>searchObservations(await analysisWorkspace(args.workspace),args.query,args.limit)));
  server.registerTool('carve_observation',{description:'Page recorded pseudocode/text with evidence identity, provider and current/historical inventory label. Static evidence is not original source.',inputSchema:{...workspace,id:z.string(),offset:z.number().int().nonnegative().optional(),limit:z.number().int().min(1).max(12000).optional()},annotations:{readOnlyHint:true,openWorldHint:false}},args=>guarded(async()=>readObservation(await analysisWorkspace(args.workspace),args.id,args.offset,args.limit)));
  server.registerTool('carve_trace',{description:'Trace bounded string-to-code/data references, indexed data windows, raw-pointer interpretations and static native calls. Reports missing edges/truncation; neighboring registrations are leads, not semantic confirmation or a complete boundary.',inputSchema:{...workspace,id:z.string(),depth:z.number().int().min(0).max(8).optional(),maxNodes:z.number().int().min(1).max(200).optional()},annotations:{readOnlyHint:true,openWorldHint:false}},args=>guarded(async()=>traceBoundary(await analysisWorkspace(args.workspace),args.id,args)));
