  server.registerTool('carve_verify_reconstruction',{description:'Execute a trusted original/candidate comparison, persist complete results and return a budgeted recorded summary by default. Read its pinned ID with carve_verification for cases/unknowns/reference/runtime metadata. fullReport:true explicitly returns the legacy unbounded report. Reference@3 and Android-reference@4 compare ordered stateful sequences within one fresh process per sequence. Requires execute:true; command/Android references retain their declared scope. Passing cases do not prove UI/server/hardware equivalence.',inputSchema:{...workspace,package:z.string(),cases:z.string(),reference:z.string(),execute:z.literal(true),timeoutMs:z.number().int().min(50).max(30000).optional(),fullReport:z.boolean().optional(),budgetBytes:z.number().int().min(1024).max(65536).optional()},annotations:{readOnlyHint:false,openWorldHint:true}},(args,extra)=>guarded(async()=>{
    const root=await analysisWorkspace(args.workspace),result=await verifyReconstruction(root,{package:await confined(base,args.package),cases:await confined(base,args.cases),reference:await confined(base,args.reference),execute:args.execute,timeoutMs:args.timeoutMs,signal:extra.signal,authorizeWorkspace:analysisWorkspace,authorizePath:analysisPath});return args.fullReport?result:verificationResponse(root,result,args.budgetBytes);
  }));
  server.registerTool('carve_verification',{description:'Read a pinned recorded verification archive without executing code or revalidating current original inputs. Fresh index/full-report checksums; selected case files checked on read. Summary/case cards and JSON text excerpts have a compact UTF8 budget. Follow nextOffset; unknowns/limitations and complete values remain on disk. Hashes identify local records, not signatures or newly established behavior.',inputSchema:{...workspace,id:z.string().regex(/^[a-f0-9]{64}$/),view:z.enum(verificationViews).optional(),offset:z.number().int().nonnegative().optional(),limit:z.number().int().min(1).max(100).optional(),failedOnly:z.boolean().optional(),caseIndex:z.number().int().min(0).max(199).optional(),field:z.string().min(1).max(100).optional(),item:z.number().int().nonnegative().optional(),characters:z.number().int().min(1).max(12000).optional(),budgetBytes:z.number().int().min(1024).max(65536).optional()},annotations:{readOnlyHint:true,openWorldHint:false}},args=>guarded(async()=>readVerificationArchive(await analysisWorkspace(args.workspace),args)));
  server.registerTool('carve_unpack',{description:'Extract one resumable batch of ZIP/APK/IPA/JAR/AAB/AAR members with explicit entry/file/byte budgets and CRC32/SHA256 checks. Refuses unsafe paths, symlinks, special files and encrypted entries. Does not execute or decrypt target code; index content separately.',inputSchema:{...workspace,file:z.string(),maxFiles:z.number().int().min(1).max(1000000).optional(),maxEntries:z.number().int().min(1).max(1000000).optional(),maxBytes:z.number().int().min(1).max(1024**4).optional(),maxFileBytes:z.number().int().min(1).max(1024**4).optional()},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false}},(args,extra)=>guarded(async()=>unpackContainer(await analysisWorkspace(args.workspace),{...args,signal:extra.signal})));
  server.registerTool('carve_analysis_enqueue',{description:'Record1–100 selected component analysis requests in SQLite with fresh source hashes and configured provider identity. Native/DEX scopes use existing engines; JS modules use static inspection. Unsupported formats remain explicit. Does not execute target code or infer a feature boundary.',inputSchema:{...workspace,requests:z.array(analysisRequest).min(1).max(100)},annotations:{readOnlyHint:false,destructiveHint:false,openWorldHint:false}},(args,extra)=>guarded(async()=>enqueueAnalysis(await analysisWorkspace(args.workspace),args.requests,engines,extra.signal)));
  server.registerTool('carve_analysis_jobs',{description:'Page durable analysis jobs/attempts. Running rows include actual owner/process-group inspection; unknown liveness prevents recovery. Completed means a bounded static-analysis request, not reconstructed or verified behavior.',inputSchema:{...workspace,id:z.string().optional(),status:z.string().optional(),limit:z.number().int().min(1).max(100).optional(),offset:z.number().int().nonnegative().optional()},annotations:{readOnlyHint:true,openWorldHint:false}},args=>guarded(async()=>queryAnalysisJobs(await analysisWorkspace(args.workspace),args)));
  server.registerTool('carve_analysis_run',{description:'Run1–10 queued static-analysis requests synchronously using startup-configured engines. Rechecks source/provider identity, preserves attempts/logs and registers guarded engine groups before launch. Failed/interrupted jobs need retry:true; changed identities need re-enqueue. Cancellation terminates owned groups. Does not execute target code or claim feature equivalence.',inputSchema:{...workspace,maxJobs:z.number().int().min(1).max(10).optional(),retry:z.boolean().optional()},annotations:{readOnlyHint:false,openWorldHint:false}},(args,extra)=>guarded(async()=>engineJob(async()=>{
    let counter=0;return runAnalysisQueue(await analysisWorkspace(args.workspace),{engines,maxJobs:args.maxJobs,retry:args.retry,signal:extra.signal,onProgress:async progress=>{const token=extra._meta?.progressToken;if(token!==undefined)await extra.sendNotification({method:'notifications/progress',params:{progressToken:token,progress:++counter,message:JSON.stringify(progress)}});}});
  })));
  server.registerTool('carve_analysis_start',{description:'Start a bounded local background batch using startup-configured engines and return a run ID. After start returns, normal MCP disconnect or a later status-call timeout leaves it running; use carve_analysis_cancel. Cancelling an in-flight start requests cancellation of its newly created run. One execution lease per workspace; no global background-engine limit. Existing active run is returned without changing its options. Inspect runs/jobs and actual liveness; completion means static analysis only.',inputSchema:{...workspace,maxJobs:z.number().int().min(1).max(10).optional(),retry:z.boolean().optional(),maxRunMs:z.number().int().min(1000).max(86400000).optional()},annotations:{readOnlyHint:false,openWorldHint:false}},(args,extra)=>guarded(async()=>startAnalysisRun(await analysisWorkspace(args.workspace),{engines,maxJobs:args.maxJobs,retry:args.retry,maxRunMs:args.maxRunMs,signal:extra.signal})));
  server.registerTool('carve_analysis_runs',{description:'Page durable background batches with recorded and observed status, actual worker/supervisor/group liveness, logs, progress and result hashes. Missing workers are interrupted, never assumed complete. Inspect component jobs and evidence separately.',inputSchema:{...workspace,id:z.string().optional(),limit:z.number().int().min(1).max(100).optional(),offset:z.number().int().nonnegative().optional()},annotations:{readOnlyHint:true,openWorldHint:false}},args=>guarded(async()=>queryAnalysisRuns(await analysisWorkspace(args.workspace),args)));
  server.registerTool('carve_analysis_cancel',{description:'Persist cancellation for a returned background run ID. Its worker stops owned tools. A cancelling response does not mean processes are already gone; query carve_analysis_runs. Does not send signals to recorded PIDs or cancel other workspaces.',inputSchema:{...workspace,id:z.string()},annotations:{readOnlyHint:false,openWorldHint:false}},args=>guarded(async()=>cancelAnalysisRun(await analysisWorkspace(args.workspace),args.id)));
  await server.connect(new StdioServerTransport());
